// src/learner/subject.js
var subjectOfCskill = (code) => SUBJECT_PREFIXES[String(code || "").split(".")[0]] || null;

// src/learner/evidence.js
var OUTCOME_PREFIX = new RegExp(`^(${Object.keys(SUBJECT_PREFIXES).filter((k) => k !== "MATH").join("|")})\\.`);
function homeworkEvidence({ homework, sitting, answer }) {
  const item = (sitting?.items || [])[Number(answer?.n) - 1];
  if (!item?.cskill || !homework?.door_id || !sitting?.learner_ref) return null;
  return {
    source: "school_homework",
    door_id: homework.door_id,
    learner_ref: sitting.learner_ref,
    subject: subjectOfCskill(item.cskill) || "math",
    skill_id: item.cskill,
    cskill: item.cskill,
    correct: !!answer.correct,
    misconception: answer.mis || null,
    independent: true,
    marks: answer.correct ? 1 : 0,
    max_marks: 1,
    item_ref: `hw:${sitting.homework_id || homework.id}:${answer.n}${item.recheck ? ":recheck" : ""}`,
    submitted_value: answer.chosen ? String(answer.chosen).slice(0, 500) : null,
    client_ts: answer.at || null,
    hints_used: 0,
    attempt_no: 1
  };
}

// src/school/homeworkLearner.js
var CODE = /^[A-Z2-9]{10}$/;
var ok2 = (body) => ({ status: 200, body: { success: true, ...body } });
var no2 = (status, error, more = {}) => ({ status, body: { success: false, error, ...more } });
var resultsBody = (hw, sittings) => ({ action: "homework_results", results: { [hw.homework_ref]: resultsFor(sittings) } });
async function learnerHomework(p, deps) {
  const { store } = deps;
  if (p?.action === "learner_home") return learnerHome(p, deps);
  const code = String(p?.code || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
  if (!CODE.test(code)) return no2(404, "This link is not right. Ask the teacher for it again.");
  const found = await store.sittingByCode(code);
  if (!found) return no2(404, "This link is not right. Ask the teacher for it again.");
  const { sitting, homework, door } = found;
  const s0 = { ...sitting, mode: homework.mode };
  const head = { title: homework.title, due_on: homework.due_on, count: (sitting.items || []).length, mode: homework.mode };
  if (homework.mode === "paper") return ok2({ ...head, view: { status: "paper" } });
  const done = async (s) => {
    await store.saveSitting(s);
    if ((s.status === "submitted" || s.status === "locked") && deps.push && door?.results_url) {
      try {
        if (await deps.push(door, resultsBody(homework, [s]))) await store.saveSitting({ ...s, pushed_at: new Date(deps.now()).toISOString() });
      } catch {
      }
    }
  };
  if (p.action === "open") return ok2({ ...head, view: sittingView(s0) });
  if (p.action === "start") {
    const r = step(s0, { type: "start" }, deps.now());
    if (!r.ok) return ok2({ ...head, view: sittingView(s0) });
    if (r.s !== s0) await store.saveSitting(r.s);
    return ok2({ ...head, view: sittingView(r.s) });
  }
  if (p.action === "answer") {
    const r = step(s0, { type: "answer", n: p.n, response: p.response }, deps.now());
    if (!r.ok) return ok2({ ...head, refused: r.error, view: sittingView(s0) });
    await done(r.s);
    try {
      const row = homeworkEvidence({ homework, sitting, answer: r.s.answers[r.s.answers.length - 1] });
      if (row && store.saveEvidence) await store.saveEvidence(row);
    } catch {
    }
    const it = s0.items[Number(p.n) - 1];
    const right = it.kind === "choice" ? it.options.find((o) => o.right) : null;
    const reason = !r.mark.correct ? it.kind === "choice" ? it.options.find((o) => o.key === r.mark.chosen)?.why : (it.wrong || []).find((w) => w.mis && w.mis === r.mark.mis)?.why : "";
    return ok2({ ...head, mark: { correct: r.mark.correct, answer: right ? `${right.key}. ${right.text}` : it.answer, why: reason || "" }, view: sittingView(r.s) });
  }
  if (p.action === "leave") {
    const r = step(s0, { type: "leave", reason: p.reason }, deps.now());
    if (r.ok && r.s !== s0) await done(r.s);
    return ok2({ ...head, view: sittingView(r.ok ? r.s : s0) });
  }
  return no2(400, "Unknown action");
}

// src/school/homeworkStore.js
var SITTING_COLS = [
  "id",
  "homework_id",
  "learner_ref",
  "code",
  "seed",
  "version",
  "items",
  "answers",
  "status",
  "started_at",
  "finished_at",
  "locked_at",
  "lock_reason",
  "lock_question",
  "reopen_count",
  "pushed_at"
];
var pickCols = (s) => Object.fromEntries(SITTING_COLS.filter((k) => s[k] !== void 0).map((k) => [k, s[k]]));
function supabaseStore(admin) {
  return {
    async getHomework(doorId, ref) {
      const { data } = await admin.from("school_homework").select("*").eq("door_id", doorId).eq("homework_ref", ref).maybeSingle();
      return data || null;
    },
    async saveHomework(row) {
      const { data, error } = await admin.from("school_homework").insert(row).select("*").single();
      if (error) throw new Error("Not saved");
      return data;
    },
    async sittingsOf(homeworkId) {
      const { data } = await admin.from("school_homework_sittings").select("*").eq("homework_id", homeworkId).order("learner_ref").limit(2e3);
      return data || [];
    },
    async saveSittings(rows) {
      for (let i = 0; i < rows.length; i += 100) {
        const { error } = await admin.from("school_homework_sittings").insert(rows.slice(i, i + 100).map(pickCols));
        if (error) throw new Error("Not saved");
      }
    },
    async sittingByCode(code) {
      const { data } = await admin.from("school_homework_sittings").select("*, school_homework(*, school_doors(id, code, secret, active, results_url))").eq("code", code).maybeSingle();
      if (!data || !data.school_homework?.school_doors?.active) return null;
      const { school_homework: hw, ...sitting } = data;
      const { school_doors: door, ...homework } = hw;
      return { sitting, homework, door };
    },
    async saveSitting(s) {
      const { id, ...rest } = pickCols(s);
      await admin.from("school_homework_sittings").update({ ...rest, updated_at: (/* @__PURE__ */ new Date()).toISOString() }).eq("id", id);
    },
    // One evidence row for the learner's log (response_events, migration 20261111_learner_evidence.sql). A duplicate
    // (the unique index on source, item_ref and learner) is the row already being there, which is what the log wants.
    async saveEvidence(row) {
      const { error } = await admin.from("response_events").insert(row);
      if (error && error.code !== "23505") throw new Error("Not saved");
    },
    // School exam evidence (evidenceDoor.js): what is already in the log for these items, new rows in batches, a corrected mark in place.
    async examEvidence(doorId, itemRefs) {
      const out = [];
      for (let i = 0; i < itemRefs.length; i += 100) {
        const { data, error } = await admin.from("response_events").select("id, item_ref, learner_ref, marks, max_marks, outcome_code, substrand_code").eq("source", "school_exam").eq("door_id", doorId).in("item_ref", itemRefs.slice(i, i + 100)).limit(2e4);
        if (error) throw new Error("Not read");
        out.push(...data || []);
      }
      return out;
    },
    // Everything the log holds for these school learners, by reference (class_rechecks, recheckDoor.js): school rows by
    // door and reference, practice rows where the learner is linked to a HOREB child. Evidence columns only.
    async learnerEvidence(doorId, refs) {
      const COLS = "source, skill_id, cskill, outcome_code, substrand_code, correct, marks, max_marks, independent, hints_used, difficulty, item_ref, client_ts, created_at";
      const out = {};
      for (let i = 0; i < refs.length; i += 50) {
        const part = refs.slice(i, i + 50);
        const { data, error } = await admin.from("response_events").select(`learner_ref, ${COLS}`).eq("door_id", doorId).in("learner_ref", part).limit(2e4);
        if (error) throw new Error("Not read");
        for (const r of data || []) {
          const { learner_ref, ...row } = r;
          (out[learner_ref] ||= []).push(row);
        }
        const { data: links, error: le } = await admin.from("school_learner_links").select("learner_ref, parent_id, child_id").eq("door_id", doorId).in("learner_ref", part);
        if (le) throw new Error("Not read");
        const byPair = new Map((links || []).map((l) => [`${l.parent_id}|${l.child_id}`, l.learner_ref]));
        const parents = [...new Set((links || []).map((l) => l.parent_id))], kids = [...new Set((links || []).map((l) => l.child_id))];
        if (parents.length) {
          const { data: rows, error: pe } = await admin.from("response_events").select(`student_id, learner_id, ${COLS}`).in("student_id", parents).in("learner_id", kids).eq("source", "practice").limit(2e4);
          if (pe) throw new Error("Not read");
          for (const r of rows || []) {
            const ref = byPair.get(`${r.student_id}|${r.learner_id}`);
            if (!ref) continue;
            const { student_id, learner_id, ...row } = r;
            (out[ref] ||= []).push(row);
          }
        }
      }
      return out;
    },
    async insertEvidence(rows) {
      for (let i = 0; i < rows.length; i += 200) {
        const { error } = await admin.from("response_events").insert(rows.slice(i, i + 200));
        if (error && error.code === "23505") {
          for (const r of rows.slice(i, i + 200)) {
            const e = (await admin.from("response_events").insert(r)).error;
            if (e && e.code !== "23505") throw new Error("Not saved");
          }
        } else if (error) throw new Error("Not saved");
      }
    },
    async updateEvidence(id, patch) {
      const { error } = await admin.from("response_events").update(patch).eq("id", id).eq("source", "school_exam");
      if (error) throw new Error("Not saved");
    },
    // The learner home (learnerHome.js, migration 20261111_learner_home.sql).
    async homeDoor(code) {
      const { data } = await admin.from("school_doors").select("id, code, name, secret, active").eq("code", code).maybeSingle();
      return data && data.active ? data : null;
    },
    async homeSittings(doorId, ref) {
      const { data } = await admin.from("school_homework_sittings").select("code, status, items, answers, started_at, finished_at, locked_at, lock_question, school_homework!inner(door_id, title, mode, due_on, created_at)").eq("learner_ref", ref).eq("school_homework.door_id", doorId).order("updated_at", { ascending: false }).limit(60);
      return (data || []).map(({ school_homework: homework, ...sitting }) => ({ sitting, homework }));
    },
    async homeTries(key, sinceIso) {
      const { count } = await admin.from("school_home_attempts").select("id", { count: "exact", head: true }).eq("try_key", key).eq("ok", false).gte("at", sinceIso);
      return count || 0;
    },
    async homeTry(key, ok3) {
      await admin.from("school_home_attempts").insert({ try_key: key, ok: ok3 });
      await admin.from("school_home_attempts").delete().eq("try_key", key).lt("at", new Date(Date.now() - 864e5).toISOString());
    },
    async childLink(userId, childId) {
      const { data } = await admin.from("school_learner_links").select("learner_ref, linked_at, school_doors(id, code, name, active)").eq("parent_id", userId).eq("child_id", childId).order("linked_at", { ascending: false }).limit(5);
      const l = (data || []).find((x) => x.school_doors?.active);
      return l ? { door: { id: l.school_doors.id, code: l.school_doors.code, name: l.school_doors.name }, learner_ref: l.learner_ref } : null;
    }
  };
}

// scripts/school-homework.template.ts
var env = (k) => Deno.env.get(k) || "";
var ORIGINS = ["https://tutagora.com", "https://www.tutagora.com", "capacitor://localhost", "https://localhost"];
var cors = (req) => {
  const o = req.headers.get("origin") || "";
  return {
    "access-control-allow-origin": ORIGINS.includes(o) ? o : ORIGINS[0],
    "access-control-allow-headers": "authorization, x-client-info, apikey, content-type",
    "access-control-allow-methods": "POST, OPTIONS",
    vary: "origin"
  };
};
var ipKey = async (req) => {
  const ip = (req.headers.get("x-forwarded-for") || "").split(",")[0].trim() || req.headers.get("cf-connecting-ip") || req.headers.get("x-real-ip") || "unknown";
  const d = await crypto.subtle.digest("SHA-256", new TextEncoder().encode("learner-home:" + ip));
  return Array.from(new Uint8Array(d)).slice(0, 16).map((b) => b.toString(16).padStart(2, "0")).join("");
};
var push = async (door, body) => {
  const text = JSON.stringify(body);
  const time = String(Math.floor(Date.now() / 1e3));
  const r = await fetch(door.results_url, { method: "POST", headers: {
    "content-type": "application/json",
    "x-door-code": door.code,
    "x-door-time": time,
    "x-door-sign": await signCall(door.secret, time, text)
  }, body: text });
  return r.ok;
};
Deno.serve(async (req) => {
  const h = cors(req);
  if (req.method === "OPTIONS") return new Response(null, { status: 204, headers: h });
  if (req.method !== "POST") return new Response(JSON.stringify({ success: false, error: "POST only" }), { status: 405, headers: { ...h, "content-type": "application/json" } });
  const text = await req.text();
  if (text.length > 4e3) return new Response(JSON.stringify({ success: false, error: "Too large" }), { status: 413, headers: { ...h, "content-type": "application/json" } });
  let p;
  try {
    p = JSON.parse(text);
  } catch {
    p = null;
  }
  const admin = createClient(env("SUPABASE_URL"), env("SUPABASE_SERVICE_ROLE_KEY"));
  const token = (req.headers.get("authorization") || "").replace(/^Bearer\s+/i, "");
  const userId = async () => {
    if (!token || token === env("SUPABASE_ANON_KEY")) return null;
    const { data } = await admin.auth.getUser(token);
    return data?.user?.id || null;
  };
  const r = await learnerHomework(p || {}, { store: supabaseStore(admin), now: () => Date.now(), push, ipKey: await ipKey(req), userId }).catch(() => ({ status: 500, body: { success: false, error: "Something went wrong. Try again." } }));
  return new Response(JSON.stringify(r.body), { status: r.status, headers: { ...h, "content-type": "application/json" } });
});
